WITH last_location_events AS (SELECT GET_JSON_OBJECT(metadata, event_data.TaskAttributes.call_sid) AS id_call, MAX(GET_JSON_OBJECT(metadata, event_data.Sid)) AS id_last_event, year, month, day FROM datalake_bigfone_events.events WHERE provider = 'twilio' AND (GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Anyone' OR GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Flex') AND NOT GET_JSON_OBJECT(metadata, event_data.TaskAttributes.from_city) IS NULL AND year = STRUCT(year AS year) AND month = STRUCT(month AS month) AND day = STRUCT(day AS day) GROUP BY 1, 3, 4, 5) SELECT lle.id_call, NULLIF(GET_JSON_OBJECT(cfe.metadata, event_data.TaskAttributes.from_city), '') AS from_city, NULLIF(GET_JSON_OBJECT(cfe.metadata, event_data.TaskAttributes.from_state), '') AS from_state, NULLIF(GET_JSON_OBJECT(cfe.metadata, event_data.TaskAttributes.from_country), '') AS from_country, lle.year, lle.month, lle.day FROM datalake_bigfone_events.events AS cfe INNER JOIN last_location_events AS lle ON GET_JSON_OBJECT(cfe.metadata, event_data.Sid) = lle.id_last_event WHERE cfe.provider = 'twilio' AND (GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Anyone' OR GET_JSON_OBJECT(metadata, event_data.WorkflowName) = 'Assign to Flex') AND cfe.year = STRUCT(year AS year) AND cfe.month = STRUCT(month AS month) AND cfe.day = STRUCT(day AS day)